import re

from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.egate.genericepcsim import GenericEPCSIMCommand

__author__ = "Adrianna Pienkowska, Bartosz Odziomek"
__copyright__ = "Copyright (C) 2018, Nokia"
__email__ = "adrianna.pienkowska@nokia.com, bartosz.odziomek@nokia.com"


class Start(GenericEPCSIMCommand):
    """Start command class."""

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Start command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Start, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.current_ret["WARN"] = []
        self.options = options

        # private variables
        self._is_at_the_end = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "start"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_ornaments(line)
                self._parse_state(line)
                self._parse_warnings(line)
            except ParsingDone:
                pass
        return super(Start, self).on_new_line(line, is_full_line)

    _re_error = re.compile(r"(?P<ERROR>(Error:|ERR:).*)\.?")

    def _parse_error(self, line):
        if self._regex_helper.search_compiled(Start._re_error, line):
            self.set_exception(CommandFailure(self, f"Error: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone

    _re_ornaments = re.compile(r"(?P<ORNA>\*+)")

    def _parse_ornaments(self, line):
        if self._regex_helper.search_compiled(Start._re_ornaments, line) and not self._is_at_the_end:
            self._is_at_the_end = True
            raise ParsingDone

    _re_state = re.compile(r"CHANGE STATE:\s(?P<STATE>\w+)")

    def _parse_state(self, line):
        if self._regex_helper.search_compiled(Start._re_state, line) and self._is_at_the_end:
            state = self._regex_helper.group("STATE").strip()
            if state != "ACTIVE":
                self.set_exception(CommandFailure(self, f"ERROR: state not ACTIVE, state {state}"))
            else:
                self.current_ret["STATE"] = state
            raise ParsingDone

    _re_warn = re.compile(r"WARN:\s(?P<WARN>.*)")

    def _parse_warnings(self, line):
        if self._regex_helper.search_compiled(Start._re_warn, line):
            self.current_ret["WARN"].append(self._regex_helper.group("WARN").strip())
            raise ParsingDone


